function [coupled,timingNull,time,parts,cfg]=v3_ha_generator(beta,amplitude,duration,fp,fa,signalStream,poissonStream)
% Frozen HA generator. Caller draws frequencies on an independent stream.
% No signal is generated by loading this function. Seed/order are external.
old=RandStream.getGlobalStream;cleanup=onCleanup(@() RandStream.setGlobalStream(old)); %#ok<NASGU>
RandStream.setGlobalStream(signalStream);
cfg=struct('fs_hz',1000,'duration_s',duration,'beta',beta,'noise_sd',1, ...
 'true_fp_hz',fp,'rhythm_amplitude',amplitude,'true_fa_hz',fa, ...
 'burst_sigma_s',.01,'burst_amplitude',1.5,'cycle_keep_probability',.55, ...
 'jitter_sd_s',.005,'background_burst_scale',.18,'timing_null_rate_hz',.55*fp);
time=0:1/cfg.fs_hz:duration-1/cfg.fs_hz;n=numel(time);
noise=powerlaw_noise(n,beta);rhythm=amplitude*sin(2*pi*fp*time);
cycles=(.75/fp):1/fp:time(end);keep=rand(size(cycles))<.55;
centers=cycles(keep)+.005*randn(1,sum(keep));
envelope=gaussian_envelope(time,centers,.01);
carrier=sin(2*pi*fa*time);trueComponent=1.5*envelope.*carrier;
% Development sparsity-generator background recipe: jittered uniform times,
% peak-normalized envelope, the same carrier, scale 0.18 of burst amplitude.
backgroundTimes=linspace(time(1),time(end),numel(cycles)+2);
backgroundTimes=backgroundTimes(2:end-1);
backgroundTimes=backgroundTimes+(.45/fp)*(2*rand(size(backgroundTimes))-1);
backgroundTimes=min(max(backgroundTimes,time(1)),time(end));
backgroundEnvelope=gaussian_envelope(time,backgroundTimes,.01);
if max(backgroundEnvelope)>0,backgroundEnvelope=backgroundEnvelope/max(backgroundEnvelope);end
background=1.5*.18*backgroundEnvelope.*carrier;
% Independent null stream leaves every signal/background draw paired.
nullCenters=[];s=-log(max(rand(poissonStream),realmin))/(.55*fp);
while s<duration
 nullCenters(end+1)=s;s=s-log(max(rand(poissonStream),realmin))/(.55*fp); %#ok<AGROW>
end
nullEnvelope=gaussian_envelope(time,nullCenters,.01);
nullComponent=1.5*nullEnvelope.*carrier;
coupled=noise+rhythm+background+trueComponent;
timingNull=coupled-trueComponent+nullComponent;
pairResidual=max(abs((coupled-timingNull)-(trueComponent-nullComponent)));
assert(pairResidual<=1e-12,'v3:NullPair','HA timing null changed other components');
parts=struct('noise',noise,'rhythm',rhythm,'carrier',carrier, ...
 'background_component',background,'background_times_s',backgroundTimes, ...
 'true_component',trueComponent,'true_envelope',envelope,'event_times_s',centers, ...
 'null_component',nullComponent,'null_envelope',nullEnvelope,'poisson_times_s',nullCenters, ...
 'pair_residual',pairResidual);
end
function env=gaussian_envelope(time,centers,sigma)
env=zeros(size(time));for j=1:numel(centers),env=env+exp(-.5*((time-centers(j))/sigma).^2);end
end
function x=powerlaw_noise(n,alpha)
% Identical power-law construction to the Phase-A development generator.
freqs=0:n-1;amp=ones(1,n);valid=freqs>0&freqs<=floor(n/2);amp(valid)=1./freqs(valid).^(alpha/2);
phaseRand=2*pi*rand(1,n);spectrum=amp.*exp(1i*phaseRand);spectrum(1)=0;
if mod(n,2)==0
 posIdx=2:n/2;negIdx=n:-1:n/2+2;spectrum(negIdx)=conj(spectrum(posIdx));spectrum(n/2+1)=real(spectrum(n/2+1));
else
 posIdx=2:(n+1)/2;negIdx=n:-1:(n+3)/2;spectrum(negIdx)=conj(spectrum(posIdx));
end
x=real(ifft(spectrum));x=x-mean(x);x=x/max(std(x),eps);
end
